Tidy data: benefits are stuck in wide format

survey_2017_raw |&gt;
  select(respondent_id, starts_with("benefit_")) |&gt;
  head()








Function


One respondent has a single true preference, but right now it’s scattered across six separate columns. Before we can do anything useful with it, we need to reshape it with pivot_longer().

Tidy data: pivot_longer()

benefits_2017_long &lt;- survey_2017_raw |&gt;
  pivot_longer(
    cols = starts_with("benefit_"),
    names_to = "benefit_type",
    values_to = "response"
  ) |&gt;
  mutate(chosen = response %in% c("Yes", "Y", "yes")) |&gt;
  group_by(respondent_id) |&gt;
  summarize(
    benefit_preference = if (any(chosen)) benefit_type[chosen][1] else NA_character_,
    .groups = "drop"
  )

survey_2017_clean &lt;- survey_2017_raw |&gt;
  select(-starts_with("benefit_")) |&gt;
  left_join(benefits_2017_long, by = "respondent_id")

Back to the Income Example







Solution


Before income can be used in any calculation, the income data needs to be transformed into a real number.





clean_income &lt;- function(x) {
  x &lt;- str_trim(x)
  is_k &lt;- str_detect(x, "K$")
  numeric_part &lt;- x |&gt;
    str_remove_all("[$,K]") |&gt;
    as.numeric()
  if_else(is_k, numeric_part * 1000, numeric_part)
}

survey_2017_clean &lt;- survey_2017_clean |&gt;
  mutate(income = clean_income(income))

survey_2022_clean &lt;- survey_2022_clean |&gt;
  mutate(income = clean_income(income))

Setup and data
We are bringing in another table: drinks, which includes information about beverages.
library(dplyr); library(tidyr); library(tibble); library(readr)
library(ggplot2); library(stringr); library(forcats); library(lubridate)

survey &lt;- read.csv("data/sleep_survey_v2.csv", na.strings = c("", "NA"),
                   fileEncoding = "WINDOWS-1252") |&gt;
  as_tibble() |&gt;
  mutate(survey_date = ymd_hms(survey_date))

drinks &lt;- read.csv("data/drinks.csv", fileEncoding = "WINDOWS-1252") |&gt;
  as_tibble()

Where is the missing?
survey |&gt;
  mutate(
    bedtime = if_else(
      str_detect(bedtime, regex("\\d|midnight", ignore_case = TRUE)),
      bedtime, NA_character_
    )
  ) |&gt;
  select(program, sleep_hours, stress_level, favourite_drink,
         has_early_class, avg_grade, bedtime) |&gt;
  mutate(across(-program, is.na)) |&gt;
  group_by(program) |&gt;
  summarize(across(everything(), mean)) |&gt;
  pivot_longer(-program, names_to = "question", values_to = "share") |&gt;
  ggplot(aes(x = question, y = program, fill = share)) +
  geom_tile(colour = "white", linewidth = 0.8) +
  scale_x_discrete(guide = guide_axis(n.dodge = 2)) +
  scale_fill_gradient(
    low = "white", high = "firebrick",
    limits = c(0, NA),
    labels = scales::percent,
    name = "Proportion"
  ) +
  labs(title = "Which students missed responses the most?", x = NULL, y = NULL) +
  theme_minimal(base_size = 14)

