Sleep and caffeine
survey_drinks |&gt;
  filter(!is.na(favourite_drink)) |&gt;
  group_by(favourite_drink, caffeine_mg) |&gt;
  summarize(mean_sleep = mean(sleep_hours, na.rm = TRUE), .groups = "drop") |&gt;
